SELECT DISTINCT ?person ?personLabel ?account1 ?account2 WHERE {
  ?person wdt:[property:instance of] wd:[entity:human] .

  {
    ?person wdt:[property:Twitter username] ?account1 .
    ?person wdt:[property:Twitter username] ?account2 .
  }
  UNION
  {
    ?person wdt:[property:Instagram username] ?account1 .
    ?person wdt:[property:Instagram username] ?account2 .
  }
  UNION
  {
    ?person wdt:[property:Facebook ID] ?account1 .
    ?person wdt:[property:Facebook ID] ?account2 .
  }
  UNION
  {
    ?person wdt:[property:TikTok username] ?account1 .
    ?person wdt:[property:TikTok username] ?account2 .
  }

  FILTER(?account1 != ?account2)
  FILTER(LCASE(STR(?account1)) = LCASE(STR(?account2)))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

