BIND(YEAR(?dob) as ?birthyear).
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". ?person rdfs:label ?name. ?place rdfs:label ?birthplace}
}

SELECT ?prenomLabel (COUNT(?q) AS ?compte) WHERE {
?q wdt:P19/wdt:P131* ?dpt ; wdt:P735 ?prenom .
?dpt p:P131/ps:P131 wd:Q1152 ; wdt:P31 wd:Q6465 .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?prenomLabel
HAVING ( ?compte > 5 )

SELECT ?character (COUNT(DISTINCT ?item) AS ?count) WHERE {
{ ?item p:P31/ps:P31/wdt:P279* wd:Q341. } UNION
{ ?item wdt:P31/wdt:P279* wd:Q7397; wdt:P275/(wdt:P31|wdt:P279)* wd:Q3943414. }
?item rdfs:label ?label.
FILTER(LANG(?label) = "en")
BIND(UCASE(SUBSTR(?label, 1, 1)) AS ?character)
}
GROUP BY ?character

SELECT ?person ?personLabel ?group ?groupLabel ("7FFF00" as ?rgb)
WHERE {
?person wdt:P570 ?death FILTER (YEAR(?death) < 1800).
?person wdt:P463 wd:Q123885. # That ?person is a person is implicit through membership
?person wdt:P463 ?group FILTER (?group != wd:Q123885).
?group wdt:P31/wdt:P279? wd:Q955824.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?t ?ppLabel ?valueLabel ?rrLabel ?image
WHERE
{
{wd:Q9711 ?prop ?t FILTER (datatype(?t)=xsd:dateTime) .
?value wikibase:directClaim ?prop. }
UNION
{
wd:Q9711 ?q ?statement FILTER regex (STR(?q),"prop/P") .
?statement ?p ?t FILTER regex (STR(?p), "prop/qualifier/P") FILTER (datatype(?t)=xsd:dateTime) .
?statement ?r ?value FILTER regex (STR(?r),"prop/statement/") .
BIND(IRI(CONCAT(CONCAT(SUBSTR(STR(?r),1,29),"direct/"),SUBSTR(STR(?r),40))) as ?rprop)
?rr wikibase:directClaim ?rprop .
BIND(IRI(CONCAT(CONCAT(SUBSTR(STR(?p),1,29),"direct/"),SUBSTR(STR(?p),40))) as ?pprop)
?pp wikibase:directClaim ?pprop .
OPTIONAL {?value wdt:P18 ?image}
}
UNION
{
wd:Q9711 wdt:P800 ?value .
?value ?prop ?t FILTER (datatype(?t)=xsd:dateTime) .
?rr wikibase:directClaim wdt:P800 .
?pp wikibase:directClaim ?prop.
OPTIONAL {?value wdt:P18 ?image}
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?t

select distinct ?groupLabel (?groupLabel as ?layer) ?article ?person ?personLabel ?personDescription ?graveplot ?coord ?pic ?picGrave ?WikiTree ?FindAGrave{
{
?person wdt:P119 wd:Q252312; #Place of burial
p:P119 [
pq:P965 ?graveplot;
pq:P625 ?coord].
OPTIONAL { ?person wdt:P2949 ?WikiTreeID .} # If we have a WikiTree profile
OPTIONAL { ?person wdt:P535 ?FindAGraveID .} # If we have a FindAGrave ID
OPTIONAL{ ?person wdt:P18 ?pic .} # If we have an illustration
OPTIONAL{ ?person wdt:P1442 ?picGrave .} # If we have a picture of the grave
BIND (URI(CONCAT("http://www.findagrave.com/cgi-bin/fg.cgi?page=gr&df=all&GRid=",?FindAGraveID)) AS ?FindAGrave)
BIND (URI(CONCAT("http://www.wikitree.com/wiki",?WikiTreeID)) AS ?WikiTree)
OPTIONAL {
?article schema:about ?person .
?article schema:inLanguage "en" .
?article schema:isPartOf <https://sv.wikipedia.org/> .
}
OPTIONAL {
?article schema:about ?person .
?article schema:inLanguage "sv" .
?article schema:isPartOf <https://sv.wikipedia.org/> .
}
OPTIONAL { ?person wdt:P106 ?group .} # Occupation in Layer
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en","sv"}
}
Order by ?personLabel

